4098|       * original PNG format because it may not occur in the output PNG format
4099|       * and libpng deals with the issues of reading the original.
4100|       */
4101|      const unsigned int channels = PNG_IMAGE_PIXEL_CHANNELS(image->format);
4102|
4103|      /* The following checks just the 'row_stride' calculation to ensure it
4104|       * fits in a signed 32-bit value.  Because channels/components can be
4105|       * either 1 or 2 bytes in size the length of a row can still overflow 32
4106|       * bits; this is just to verify that the 'row_stride' argument can be
4107|       * represented.
4108|       */
4109|      if (image->width <= 0x7fffffffU/channels) /* no overflow */
4110|      {
4111|         png_uint_32 check;
4112|         const png_uint_32 png_row_stride = image->width * channels;
4113|
4114|         if (row_stride == 0)
4115|            row_stride = (png_int_32)/*SAFE*/png_row_stride;
4116|
4117|         if (row_stride < 0)
4118|            check = (png_uint_32)(-row_stride);
4119|
4120|         else
4121|            check = (png_uint_32)row_stride;
4122|
4123|         /* This verifies 'check', the absolute value of the actual stride
4124|          * passed in and detects overflow in the application calculation (i.e.
4125|          * if the app did actually pass in a non-zero 'row_stride'.
4126|          */
4127|         if (image->opaque != NULL && buffer != NULL && check >= png_row_stride)
4128|         {
4129|            /* Now check for overflow of the image buffer calculation; this
4130|             * limits the whole image size to 32 bits for API compatibility with
4131|             * the current, 32-bit, PNG_IMAGE_BUFFER_SIZE macro.
4132|             *
4133|             * The PNG_IMAGE_BUFFER_SIZE macro is:
4134|             *
4135|             *    (PNG_IMAGE_PIXEL_COMPONENT_SIZE(fmt)*height*(row_stride))
4136|             *
4137|             * And the component size is always 1 or 2, so make sure that the
4138|             * number of *bytes* that the application is saying are available
4139|             * does actually fit into a 32-bit number.
4140|             *
4141|             * NOTE: this will be changed in 1.7 because PNG_IMAGE_BUFFER_SIZE
4142|             * will be changed to use png_alloc_size_t; bigger images can be
4143|             * accomodated on 64-bit systems.
4144|             */
4145|            if (image->height <=
4146|                0xffffffffU/PNG_IMAGE_PIXEL_COMPONENT_SIZE(image->format)/check)
4147|            {
4148|               if ((image->format & PNG_FORMAT_FLAG_COLORMAP) == 0 ||
4149|                  (image->colormap_entries > 0 && colormap != NULL))
4150|               {
4151|                  int result;
4152|                  png_image_read_control display;
4153|
4154|                  memset(&display, 0, (sizeof display));
4155|                  display.image = image;
4156|                  display.buffer = buffer;
4157|                  display.row_stride = row_stride;
4158|                  display.colormap = colormap;
4159|                  display.background = background;
4160|                  display.local_row = NULL;
4161|
4162|                  /* Choose the correct 'end' routine; for the color-map case
4163|                   * all the setup has already been done.
4164|                   */
4165|                  if ((image->format & PNG_FORMAT_FLAG_COLORMAP) != 0)
4166|                     result =
4167|                         png_safe_execute(image,
4168|                             png_image_read_colormap, &display) &&
4169|                             png_safe_execute(image,
4170|                             png_image_read_colormapped, &display);
4171|
4172|                  else
4173|                     result =
4174|                        png_safe_execute(image,
4175|                            png_image_read_direct, &display);
4176|
4177|                  png_image_free(image);
4178|                  return result;
4179|               }
4180|
4181|               else
4182|                  return png_image_error(image,
4183|                      "png_image_finish_read[color-map]: no color-map");
4184|            }
4185|
4186|            else
4187|               return png_image_error(image,
4188|                   "png_image_finish_read: image too large");
4189|         }
4190|
4191|         else
4192|            return png_image_error(image,
4193|                "png_image_finish_read: invalid argument");
4194|      }
4195|
4196|      else
4197|         return png_image_error(image,
4198|             "png_image_finish_read: row_stride too large");
4199|   }
4200|
4201|   else if (image != NULL)
