1641|       /* But do not ignore image data handling chunks */
1642|       png_set_keep_unknown_chunks(png_ptr, PNG_HANDLE_CHUNK_AS_DEFAULT,
1643|           chunks_to_process, (int)/*SAFE*/(sizeof chunks_to_process)/5);
1644|   }
