2014|    *    base = 0;
2015|    *    entry = (231 * gray + 128) >> 8;
2016|    * }
2017|    * else if (alpha < 26) // transparent
2018|    * {
2019|    *    base = 231;
2020|    *    entry = 0;
2021|    * }
2022|    * else // partially opaque
2023|    * {
2024|    *    base = 226 + 6 * PNG_DIV51(alpha);
2025|    *    entry = PNG_DIV51(gray);
2026|    * }
2027|    */
2028|   i = 0;
2029|   while (i < 231)
